// ── Config: Feed & Search Settings ──────────────────
// Scalar importer-facing settings live in the "Set Configuration Parameters" Set node upstream —
// read them here rather than hardcoding. Structural constants (KEV_URL, SEARCH_CATEGORIES) stay
// in this Code node since a real adopter would not typically need to edit them.
const cfg = $('⚙️ SET ME: Configuration').item.json;
const PROBE_MODE = !!cfg.PROBE_MODE;
const ENABLE_CUSTOMER_STACK = !!cfg.ENABLE_CUSTOMER_STACK;
const DEMO_MODE = !!cfg.DEMO_MODE; // pairs with the inlined Stack Connector's DEMO_MODE — injects one synthetic KEV entry so CVE-to-fleet matching is reproducible with zero real credentials. Set false in the Set node once real data is wired up.

const KEV_URL = 'https://www.cisa.gov/sites/default/files/feeds/known_exploited_vulnerabilities.json';

const SEARCH_CATEGORIES = [
  { category: 'Ransomware & Campaigns', source_name: 'The Record', query: 'ransomware campaign attack this week', domains: ['therecord.media'] },
  { category: 'Vulnerability Disclosures', source_name: 'Microsoft MSRC', query: 'security vulnerability advisory this week', domains: ['msrc.microsoft.com'] },
  { category: 'MSP & Supply Chain Threats', source_name: 'Huntress', query: 'MSP supply chain threat attack this week', domains: ['huntress.com'] },
  { category: 'Industry & Compliance', source_name: 'Dark Reading', query: 'cybersecurity compliance industry news this week', domains: ['darkreading.com'] }
];

return [{ json: { PROBE_MODE, ENABLE_CUSTOMER_STACK, DEMO_MODE, KEV_URL, SEARCH_CATEGORIES } }];

// ── Config: Stack Endpoints (inlined from the standalone Customer Stack Connector) ──
// api_base/endpoint_path for each slot come from "Set Configuration Parameters" above.
// Auth is handled by a real n8n Header Auth credential attached to each slot's HTTP Request
// node below — no secret value is threaded through this Code node.
const cfg = $('⚙️ SET ME: Configuration').item.json;
const slots = [
  { tool_type: 'rmm', label: 'RMM (Syncro / NinjaOne / ConnectWise equivalent)', api_base: cfg.RMM_API_BASE, endpoint_path: cfg.RMM_ENDPOINT_PATH },
  { tool_type: 'edr', label: 'Endpoint Security / EDR platform (Heimdal / ThreatDown / SentinelOne equivalent)', api_base: cfg.EDR_API_BASE, endpoint_path: cfg.EDR_ENDPOINT_PATH },
  { tool_type: 'network', label: 'Network devices (Ubiquiti / UniFi equivalent)', api_base: cfg.NETWORK_API_BASE, endpoint_path: cfg.NETWORK_ENDPOINT_PATH }
];

const PROBE_MODE = !!cfg.PROBE_MODE;
const DEMO_MODE = !!cfg.DEMO_MODE; // when true AND no slots configured, returns a synthetic sample fleet instead of a not-configured message

const configured = slots.filter(s => s.api_base && s.api_base !== 'FILL_IN');
const skipped = slots.filter(s => !s.api_base || s.api_base === 'FILL_IN').map(s => s.label);
if (skipped.length) console.warn(`Stack Connector: skipping unconfigured slots — ${skipped.join(', ')}`);

if (configured.length === 0) {
  return [{ json: { not_configured: true, DEMO_MODE, PROBE_MODE, message: 'No stack slots configured yet — fill in the RMM/EDR/Network *_API_BASE fields in the Set Configuration Parameters node to activate a slot.' } }];
}

return configured.map(s => ({ json: { ...s, not_configured: false, PROBE_MODE, DEMO_MODE } }));

// ── Build Demo Fleet ─────────────────────────────────────────────
// Synthetic sample data so this template runs end-to-end with no real RMM/EDR/network
// credentials. Every row is clearly is_demo:true — never mistake this for a live finding.
// Mirrors the exact output shape of Normalize All Sources so a caller doesn't need to
// branch on where the data came from.
const now = new Date().toISOString();
const fleet = [
  {
    client_id: 'demo-client-01', client_name: '[DEMO] Riverside Bookkeeping',
    device_id: 'FIN-ACCT-01', hostname: 'FIN-ACCT-01', owner_role: 'Accounting Lead',
    criticality: 'finance-critical', tool: 'rmm', status: 'online',
    installed_software: [
      { name: 'Microsoft SQL Server', version: '15.0.2000.5' },
      { name: 'QuickBooks Desktop', version: '23.0' }
    ],
    risk_flags: []
  },
  {
    client_id: 'demo-client-01', client_name: '[DEMO] Riverside Bookkeeping',
    device_id: 'WKS-02', hostname: 'WKS-02', owner_role: 'Office Admin',
    criticality: 'standard', tool: 'edr', status: 'protected',
    installed_software: [ { name: 'Windows 11', version: '23H2' } ],
    risk_flags: []
  },
  {
    client_id: 'demo-client-01', client_name: '[DEMO] Riverside Bookkeeping',
    device_id: 'CORE-SW-01', hostname: 'Ubiquiti-Switch-Core', owner_role: 'Infrastructure',
    criticality: 'infrastructure', tool: 'network', status: 'online',
    installed_software: [ { name: 'UniFi Network OS', version: '7.4.162' } ],
    risk_flags: []
  }
];
return fleet.map(f => ({ json: { ...f, generated_at: now, is_demo: true } }));

// ── Build Stack Probe Report ──────────────────────────────────────
const items = $input.all();
const rows = items.map(item => {
  const j = item.json || {};
  return { source: j.label || j.tool_type || '(unknown)', api_base: j.api_base };
});
const report = rows.map(r => `${r.source} | api_base: ${r.api_base}`).join('\n');
return [{ json: { probe_report: `PROBE REPORT — Stack Connector (${rows.length} configured slots):\n${report}` } }];

// ── Normalize All Sources ───────────────────────────────────────
// Adds device-level identity, ownership, criticality, and installed-software inventory
// (or firmware, for network gear) — the fields the CVE-match step needs.
// Field-name guesses are generic; adapt to your real vendor's actual response shape
// once a slot is wired to a live API (see sticky note).
const items = $input.all();
const out = items.map(item => {
  const j = item.json || {};
  const body = j.data ?? j; // HTTP Request wraps in `data` unless Simplify enabled
  const toolType = j.tool_type || 'unknown';
  const rawSoftware = Array.isArray(body.installed_software) ? body.installed_software
    : Array.isArray(body.software) ? body.software
    : Array.isArray(body.apps) ? body.apps
    : [];
  const installed_software = rawSoftware.map(s => ({
    name: s.name ?? s.product ?? s.app_name ?? 'unknown',
    version: s.version ?? s.firmware_version ?? s.ver ?? 'unknown'
  }));
  return {
    json: {
      client_id: body.client_id ?? body.id ?? 'unknown',
      client_name: body.client_name ?? body.name ?? 'unknown',
      device_id: body.device_id ?? body.asset_id ?? body.id ?? 'unknown',
      hostname: body.hostname ?? body.device_name ?? 'unknown',
      owner_role: body.owner_role ?? body.assigned_to ?? 'unknown',
      criticality: body.criticality ?? body.tag ?? 'standard',
      tool: toolType,
      status: body.status ?? (j.error ? 'fetch_error' : 'unknown'),
      installed_software,
      risk_flags: Array.isArray(body.risk_flags) ? body.risk_flags : [],
      is_demo: false
    }
  };
});
return out.length ? out : [{ json: { not_configured: true, message: 'No stack data returned.' } }];

// Pass-through convergence point so downstream CVE-to-fleet matching logic can reference this
// node by name regardless of which upstream branch (demo fleet / not-configured / live fetch)
// actually ran this run.
return $input.all();

// Collapses the inlined Stack Connector's multi-item device list (or the skip marker) back
// to a single item so the KEV/Tavily fetch nodes below — which otherwise run once per input
// item — fire exactly once. The real fleet data stays retrievable downstream via
// $('Stack Fetch Result').isExecuted / .all(), unaffected by this collapse.
return [{ json: {} }];

const items = $input.all();
const body = items[0]?.json?.data ?? items[0]?.json ?? {};
const vulns = Array.isArray(body.vulnerabilities) ? body.vulnerabilities : [];
const cutoff = new Date(); cutoff.setDate(cutoff.getDate() - 7);
const recent = vulns.filter(v => new Date(v.dateAdded) >= cutoff).slice(0, 10);
const cfg = $('Config: Feed & Search Settings').item.json;
return recent.map(v => ({ json: {
  source_type: 'kev', cveID: v.cveID, vendorProject: v.vendorProject, product: v.product,
  vulnerabilityName: v.vulnerabilityName, dateAdded: v.dateAdded, shortDescription: v.shortDescription,
  knownRansomwareCampaignUse: v.knownRansomwareCampaignUse,
  PROBE_MODE: cfg.PROBE_MODE, ENABLE_CUSTOMER_STACK: cfg.ENABLE_CUSTOMER_STACK, DEMO_MODE: cfg.DEMO_MODE
} }));

// ── Parse CVSS Data ────────────────────
// Also extracts affected-version ranges (CPE match criteria) from the same NVD response
// already fetched — no extra API calls — for CVE-to-fleet matching in Match CVEs to Your Fleet. When DEMO_MODE is on, appends one synthetic, clearly-labeled sample CVE so that
// matching is reproducible without live KEV luck.
const kevItems = $('Filter Recent KEV Entries').all();
const nvdItems = $input.all();
const cfg = $('Config: Feed & Search Settings').item.json;

function severityFromScore(score) {
  if (score == null) return 'Unknown';
  if (score >= 9.0) return 'Critical';
  if (score >= 7.0) return 'High';
  if (score >= 4.0) return 'Medium';
  return 'Low';
}
function extractCvss(body) {
  const cve = body?.vulnerabilities?.[0]?.cve;
  if (!cve) return { score: null, severity: 'Unknown' };
  const metrics = cve.metrics || {};
  const m = metrics.cvssMetricV31?.[0] || metrics.cvssMetricV30?.[0] || metrics.cvssMetricV2?.[0];
  if (!m) return { score: null, severity: 'Unknown' };
  const score = m.cvssData?.baseScore ?? null;
  const severity = m.cvssData?.baseSeverity || severityFromScore(score);
  return { score, severity };
}
function extractAffectedVersions(body) {
  const cve = body?.vulnerabilities?.[0]?.cve;
  if (!cve) return [];
  const configs = Array.isArray(cve.configurations) ? cve.configurations : [];
  const out = [];
  for (const config of configs) {
    for (const node of (config.nodes || [])) {
      for (const match of (node.cpeMatch || [])) {
        if (match.vulnerable === false) continue;
        const parts = String(match.criteria || '').split(':');
        out.push({ vendor: parts[3] || '', product: parts[4] || '', versionStartIncluding: match.versionStartIncluding || null, versionStartExcluding: match.versionStartExcluding || null, versionEndIncluding: match.versionEndIncluding || null, versionEndExcluding: match.versionEndExcluding || null, exactVersion: (parts[5] && parts[5] !== '*') ? parts[5] : null });
      }
    }
  }
  return out;
}

const out = kevItems.map((kevItem, idx) => {
  const kev = kevItem.json;
  const nvd = nvdItems[idx]?.json || {};
  const body = nvd.data ?? nvd;
  const { score, severity } = nvd.error ? { score: null, severity: 'Unknown' } : extractCvss(body);
  const affected_versions = nvd.error ? [] : extractAffectedVersions(body);
  return { json: { ...kev, cvss_score: score, cvss_severity: severity, affected_versions, is_demo: false }, pairedItem: { item: idx } };
});

if (cfg.DEMO_MODE) {
  // Synthetic entry with no real backing input item — give it an explicit, always-valid
  // pairedItem (the last real item if one exists, else item 0) instead of leaving it unset.
  // An unset pairedItem here is exactly what produced "Paired item data for item from node
  // 'Parse CVSS Data' is unavailable" downstream in Build Slack Message, once this demo item
  // ended up being the first (or only) surviving item after dedup.
  out.push({ json: {
    source_type: 'kev', cveID: 'CVE-0000-DEMO', vendorProject: 'Microsoft', product: 'SQL Server',
    vulnerabilityName: '[DEMO] Remote code execution in SQL Server (illustrative sample entry, not a real CVE)',
    dateAdded: new Date().toISOString().slice(0, 10),
    shortDescription: 'Synthetic sample vulnerability included for template demonstration only. Pairs with the inlined Stack Connector\'s demo fleet to show end-to-end CVE-to-device matching with zero real credentials.',
    knownRansomwareCampaignUse: 'Unknown', cvss_score: 9.8, cvss_severity: 'Critical',
    affected_versions: [{ vendor: 'microsoft', product: 'sql_server', versionStartIncluding: null, versionStartExcluding: null, versionEndIncluding: '15.0.2000.5', versionEndExcluding: null, exactVersion: null }],
    is_demo: true,
    PROBE_MODE: cfg.PROBE_MODE, ENABLE_CUSTOMER_STACK: cfg.ENABLE_CUSTOMER_STACK, DEMO_MODE: cfg.DEMO_MODE
  }, pairedItem: { item: Math.max(kevItems.length - 1, 0) } });
}

return out;

const cfg = $('Config: Feed & Search Settings').item.json;
return (cfg.SEARCH_CATEGORIES || []).map(c => ({ json: {
  category: c.category, source_name: c.source_name, query: c.query, domains: c.domains,
  PROBE_MODE: cfg.PROBE_MODE, ENABLE_CUSTOMER_STACK: cfg.ENABLE_CUSTOMER_STACK
} }));

const RESULT_CAP = 8;
const CONTENT_CAP = 3000;
const queryItems = $('Expand Tavily Queries').all();
const searchItems = $input.all();
const HUB_ALLOW = /^(update-guide)$/i;
const HUB_SEG = /^(resources?|guides?|glossary|learn|academy|solutions?|platform|pricing|products?|services?|what-is|[a-z0-9-]+-(guide|hub|center|centre))$/i;
const firstSeg = (u) => { try { return new URL(u).pathname.split('/').filter(Boolean)[0] || ''; } catch (e) { return ''; } };
const toDate = (r) => new Date(r.published_date || r.publishedDate || r.published_time || 'invalid');
const isDated = (r) => !isNaN(toDate(r).getTime());
const isEvergreen = (u) => (!HUB_ALLOW.test(firstSeg(u)) && HUB_SEG.test(firstSeg(u)));
const norm = (r) => ({ title: r.title, url: r.url, content: (r.content || '').slice(0, CONTENT_CAP), published_date: isDated(r) ? toDate(r).toISOString().slice(0, 10) : null, dated: isDated(r), likely_evergreen: isEvergreen(r.url) });
const rawOf = (idx) => ((searchItems[idx]?.json?.error ? [] : ((searchItems[idx]?.json?.data ?? searchItems[idx]?.json)?.results || [])).map(norm));
const rank = (r) => (r.dated ? (r.likely_evergreen ? 1 : 0) : 2);
const ordered = (all) => (all.slice().sort((a, b) => (rank(a) - rank(b)) || ((a.published_date || '') < (b.published_date || '') ? 1 : -1)).slice(0, RESULT_CAP));
return queryItems.map((qItem, idx) => ({ json: { source_type: 'search', category: qItem.json.category, source_name: qItem.json.source_name, dated_result_count: rawOf(idx).filter(r => r.dated).length, news_result_count: rawOf(idx).filter(r => rank(r) === 0).length, results: ordered(rawOf(idx)), PROBE_MODE: qItem.json.PROBE_MODE, ENABLE_CUSTOMER_STACK: qItem.json.ENABLE_CUSTOMER_STACK } }));

// ── Filter Already-Reported Items (dedup) + Top Signal + Category Trends ──
// Drops CVEs/URLs already reported in the last 30 days and computes the top-priority CVE and
// recurring-category trends. Fleet matching happens in the next node, Match CVEs to Your Fleet.
const staticData = $getWorkflowStaticData('global');
const items = $input.all();
const PROBE_MODE = items[0]?.json?.PROBE_MODE || false;
const now = Date.now();
const THIRTY_DAYS_MS = 30 * 24 * 60 * 60 * 1000;
const FOURTEEN_DAYS_MS = 14 * 24 * 60 * 60 * 1000;

if (!staticData.reportedCves) staticData.reportedCves = {};
if (!staticData.reportedUrls) staticData.reportedUrls = {};
if (!staticData.categoryHistory) staticData.categoryHistory = {};

for (const [k, ts] of Object.entries(staticData.reportedCves)) { if (now - ts > THIRTY_DAYS_MS) delete staticData.reportedCves[k]; }
for (const [k, ts] of Object.entries(staticData.reportedUrls)) { if (now - ts > THIRTY_DAYS_MS) delete staticData.reportedUrls[k]; }
for (const cat of Object.keys(staticData.categoryHistory)) { staticData.categoryHistory[cat] = staticData.categoryHistory[cat].filter(ts => now - ts <= THIRTY_DAYS_MS); }

// out holds { json, pairedItem } so each output item keeps its TRUE upstream pairedItem — this
// node's input comes from a Merge (append mode), where each item already carries pairedItem
// data pointing back through its own branch (KEV via Parse CVSS Data, or news via Tag Tavily
// Results). A prior version hardcoded pairedItem: { item: 0 } for every output item (breaking
// the chain the instant more than one item survived dedup), and the next attempt replaced that
// with a freshly-computed { item: <position in this node's merged input> } — which still breaks
// the chain, because that flat position doesn't match either branch's real origin index once
// items from two different inputs are interleaved by the Merge node. The only correct fix is to
// forward each item's own original pairedItem unchanged.
const out = [];
let topKev = null;
const freshCategories = [];

items.forEach((item) => {
  const j = item.json;
  if (j.source_type === 'kev') {
    if (staticData.reportedCves[j.cveID]) return;
    if (!PROBE_MODE) staticData.reportedCves[j.cveID] = now;
    out.push({ json: item.json, pairedItem: item.pairedItem });
    if (typeof j.cvss_score === 'number' && (!topKev || j.cvss_score > topKev.cvss_score)) { topKev = j; }
  } else if (j.source_type === 'search') {
    const freshResults = (j.results || []).filter(r => !staticData.reportedUrls[r.url]);
    if (!PROBE_MODE) freshResults.forEach(r => { staticData.reportedUrls[r.url] = now; });
    if (freshResults.length > 0) { out.push({ json: { ...j, results: freshResults }, pairedItem: item.pairedItem }); freshCategories.push(j.category); }
  } else { out.push({ json: item.json, pairedItem: item.pairedItem }); }
});

const categoryTrends = [];
for (const cat of freshCategories) {
  if (!staticData.categoryHistory[cat]) staticData.categoryHistory[cat] = [];
  if (!PROBE_MODE) staticData.categoryHistory[cat].push(now);
  const historyForTrend = PROBE_MODE ? [...staticData.categoryHistory[cat], now] : staticData.categoryHistory[cat];
  const recentCount = historyForTrend.filter(ts => now - ts <= FOURTEEN_DAYS_MS).length;
  if (recentCount >= 3) { categoryTrends.push(`📈 ${cat}: ${recentCount} distinct incidents in the last 14 days — recurring pattern`); }
}

const topSignal = topKev ? `🔺 Top priority: ${topKev.cveID} (CVSS ${topKev.cvss_score}, ${topKev.cvss_severity}) — ${topKev.vendorProject} ${topKev.product}: ${topKev.vulnerabilityName}` : null;

if (out.length === 0) out.push({ json: { source_type: 'meta', empty: true }, pairedItem: { item: 0 } });

return out.map(({ json, pairedItem }) => ({ json: { ...json, topSignal, categoryTrends }, pairedItem: pairedItem || { item: 0 } }));

// [EMPIRICAL] Returns report as data; halted by downstream Stop and Error node.
const items = $input.all();
const kevCount = items.filter(i => i.json.source_type === 'kev').length;
const searchCount = items.filter(i => i.json.source_type === 'search').length;
const fleetCount = $('Stack Fetch Result').isExecuted ? $('Stack Fetch Result').all().length : 0;
return [{ json: { probe_report: `PROBE REPORT — Cybersecurity Briefing: ${kevCount} KEV entries, ${searchCount} Tavily results, ${fleetCount} fleet devices.` } }];

const items = $input.all().map(i => i.json);
const kevItemsAll = items.filter(x => x.source_type === 'kev');
const kevItems = kevItemsAll.filter(k => !k.is_demo);
const searchItems = items.filter(x => x.source_type === 'search');
const ENABLE_CUSTOMER_STACK = items[0]?.ENABLE_CUSTOMER_STACK;
const topSignal = items[0]?.topSignal || null;
const categoryTrends = items[0]?.categoryTrends || [];
const exposureMatches = items[0]?.exposure_matches || [];

const KEV_CATALOG_URL = 'https://www.cisa.gov/known-exploited-vulnerabilities-catalog';

const kevBlock = kevItems.length
  ? kevItems.map(k => '  - ' + k.cveID + ' (' + k.cvss_severity + ', CVSS ' + k.cvss_score + ') - ' + k.vendorProject + ' ' + k.product + ': ' + k.vulnerabilityName + '. ' + k.shortDescription + ((k.knownRansomwareCampaignUse && k.knownRansomwareCampaignUse !== 'Unknown') ? (' Known ransomware use: ' + k.knownRansomwareCampaignUse + '.') : '')).join('\n')
  : '  (no new KEV entries today)';

const marker = (r) => ((r.published_date ? r.published_date : 'UNDATED') + (r.likely_evergreen ? '  [REFERENCE PAGE - a guide/resource hub, NOT a dated news post; any date shown may be a last-modified stamp]' : ''));

const categoryBlocks = searchItems.map(s =>
  '### ' + s.category + ' (source: ' + s.source_name + ' | dated results: ' + (s.dated_result_count ?? 0) + ' | genuine news posts: ' + (s.news_result_count ?? 0) + ')\n' +
  ((s.results || []).map((r, idx) => '  [' + (idx + 1) + '] ' + r.title + '\n      URL: ' + r.url + '\n      Published: ' + marker(r) + '\n      Content: ' + r.content).join('\n') || '  (no search results)')
).join('\n\n');

const exampleShape = JSON.stringify({ updates: [ { topic: '<category name>', headline: '<one-line headline, under 15 words>', summary: '<2-3 paragraph detailed analysis as plain text, paragraphs separated by a blank line>', sources: ['<url1>', '<url2>'] } ] });

const instructions = [
  'You are writing a detailed daily cybersecurity briefing for a technical audience covering 5 categories: Active Threats & CVEs, Ransomware & Campaigns, Vulnerability Disclosures, MSP & Supply Chain Threats, and Industry & Compliance News.',
  '',
  '### Active Threats & CVEs (source: CISA Known Exploited Vulnerabilities catalog)',
  kevBlock,
  '',
  categoryBlocks,
  '',
  'For each category with genuine, substantive content (skip categories with no meaningful results rather than padding), write a detailed 2-3 paragraph analysis covering: what specifically was disclosed or reported, why it matters, and any technical or practical implications. Be specific: cite CVE IDs and CVSS scores for the Active Threats & CVEs category, and cite concrete details from the sources for the other categories.',
  '',
  '### Attribution and recency rules - these are mandatory, not stylistic',
  '1. Attribute every regulatory, compliance, legal or standards claim to whoever actually made it.',
  '2. Never state a specific numeric compliance deadline, threshold or penalty as a regulator\'s requirement unless the source attributes it to a named, citable regulatory document.',
  '3. A result marked UNDATED or [REFERENCE PAGE] is background material, not news.',
  '4. Build every analysis from the genuine dated news posts first.',
  '5. Vendor blogs and vendor guides are marketing as well as information.',
  '',
  'Sources: for the Active Threats & CVEs category, cite this URL: ' + KEV_CATALOG_URL + '. For all other categories, you MUST cite the exact source URL(s) you drew from - only use URLs that appear above, never invent one.',
  '',
  'Return ONLY valid JSON, no markdown code fences, no commentary, matching exactly this shape:',
  exampleShape,
  '',
  'If a category has no real news, omit it from the updates array entirely.'
].join('\n');

return [{ json: { prompt: instructions, ENABLE_CUSTOMER_STACK: ENABLE_CUSTOMER_STACK, topSignal: topSignal, categoryTrends: categoryTrends, exposure_matches: exposureMatches }, pairedItem: { item: 0 } }];

const j = $input.first().json;
const raw0 = (j?.content?.parts ? j.content.parts.map(p => p.text || '').join('') : null) || j?.message?.content || j?.text || '{}';
let raw = raw0.trim().replace(/^```json\s*/i, '').replace(/^```\s*/, '').replace(/```\s*$/, '');
let parsed;
try { parsed = JSON.parse(raw); } catch (e) { parsed = { updates: [], parse_error: e.message, raw_content: raw.slice(0, 500) }; }
const updates = Array.isArray(parsed.updates) ? parsed.updates : [];
const prev = $('Build AI Prompt').item.json;
return [{ json: { updates, ENABLE_CUSTOMER_STACK: prev.ENABLE_CUSTOMER_STACK, topSignal: prev.topSignal, categoryTrends: prev.categoryTrends, exposure_matches: prev.exposure_matches }, pairedItem: { item: 0 } }];

const j = $input.first().json;
const today = new Date().toLocaleDateString('en-CA', { timeZone: 'Asia/Bangkok' });
return [{ json: { briefing_date: today, briefing_type: 'cybersecurity', generated_at: new Date().toISOString(), updates: j.updates || [], topSignal: j.topSignal || null, categoryTrends: j.categoryTrends || [], exposure_matches: j.exposure_matches || [] }, pairedItem: { item: 0 } }];

const j = $input.first().json;
const updates = j.updates || [];
// Slack (and n8n's Slack node) can misbehave on very long single messages — long text has
// been observed to arrive split across two separate posts. Cap each item and the overall
// message so the briefing always renders as one clean Slack message.
const MAX_SUMMARY_CHARS = 400;
const MAX_TOTAL_CHARS = 2800;
const truncate = (s, n) => (s && s.length > n) ? (s.slice(0, n).trim() + '…') : s;
const body = updates.length
  ? updates.map(u => '*' + u.topic + '* — ' + u.headline + '\n' + truncate(u.summary, MAX_SUMMARY_CHARS) + (((u.sources || []).length) ? ('\n_Sources: ' + (u.sources || []).map((s, i) => '<' + s + '|source ' + (i + 1) + '>').join('  ·  ') + '_') : '')).join('\n\n')
  : '_No significant cybersecurity news today._';
const topSignalLine = j.topSignal ? (j.topSignal + '\n\n') : '';
